.topBatBox {
  width: 100%;
  height: 100%;
  position: relative;
  font-size: 14px;
  font-weight: bold;
  display: flex;
  align-items: center;
  justify-content: space-around;
}
.topBatBox .item {
  height: 30pt;
  line-height: 30pt;
  color: white;
  cursor: pointer;
  text-align: center;
  float: right;
  color: var(--lyl_topBarText);
}
.topBatBox .signOut {
  width: auto;
  margin-right: 30px;
  text-align: left;
}
.topBatBox .canChooseItem:hover {
  background-color: #83c346;
  color: white;
}
.topBatBox /deep/ .el-badge {
  width: 22px;
  margin-left: 10px;
  margin-right: 10px;
}
.topBatBox /deep/ .el-menu--horizontal > .el-submenu .el-submenu__icon-arrow {
  position: absolute;
  right: 0px;
  margin-top: -5px;
}
.topBatBox .userLoginInfo {
  vertical-align: middle;
  width: 200px;
  display: flex;
  align-items: center;
  padding-right: 10px;
}
.topBatBox .userLoginInfo img {
  margin-right: 10px;
}
